from z3 import *

def main():
    n = 6

    name_values = ["Bob", "Arnold", "Peter", "Alice", "Eric", "Carol"]
    nationality_values = ["swede", "dane", "german", "norwegian", "chinese", "brit"]
    color_values = ["red", "green", "purple", "blue", "white", "yellow"]

    name = [Int(f"name_{i}") for i in range(n)]
    nationality = [Int(f"nationality_{i}") for i in range(n)]
    color = [Int(f"color_{i}") for i in range(n)]

    solver = Solver()

    for i in range(n):
        solver.add(name[i] >= 0, name[i] < len(name_values))
        solver.add(nationality[i] >= 0, nationality[i] < len(nationality_values))
        solver.add(color[i] >= 0, color[i] < len(color_values))

    solver.add(Distinct(name))
    solver.add(Distinct(nationality))
    solver.add(Distinct(color))

    name_id = {v: i for i, v in enumerate(name_values)}
    nationality_id = {v: i for i, v in enumerate(nationality_values)}
    color_id = {v: i for i, v in enumerate(color_values)}

    def same_house(attr1, value1, attr2, value2):
        return Or([And(attr1[i] == value1, attr2[i] == value2) for i in range(n)])

    solver.add(
        Or([
            And(name[i] == name_id["Alice"], name[i + 1] == name_id["Bob"])
            for i in range(n - 1)
        ])
    )

    solver.add(
        same_house(color, color_id["green"], nationality, nationality_id["brit"])
    )

    solver.add(
        Or([
            And(name[i] == name_id["Alice"], nationality[j] == nationality_id["german"])
            for i in range(n)
            for j in range(i + 1, n)
        ])
    )

    solver.add(
        same_house(color, color_id["blue"], nationality, nationality_id["dane"])
    )

    solver.add(
        same_house(name, name_id["Eric"], color, color_id["purple"])
    )

    solver.add(name[1] == name_id["Carol"])

    solver.add(nationality[1] != nationality_id["swede"])
    solver.add(nationality[0] != nationality_id["swede"])

    solver.add(
        Or([
            And(color[i] == color_id["white"], nationality[i + 1] == nationality_id["norwegian"])
            for i in range(n - 1)
        ])
    )

    solver.add(
        Or([
            And(name[i] == name_id["Alice"], color[j] == color_id["yellow"])
            for i in range(n)
            for j in range(n)
            if abs(i - j) == 3
        ])
    )

    solver.add(nationality[4] == nationality_id["dane"])

    solver.add(
        same_house(color, color_id["blue"], name, name_id["Peter"])
    )

    if solver.check() == sat:
        model = solver.model()
        for i in range(n):
            house_name = name_values[model[name[i]].as_long()]
            house_nationality = nationality_values[model[nationality[i]].as_long()]
            house_color = color_values[model[color[i]].as_long()]
            print(f"House {i + 1}: {house_name}, {house_nationality}, {house_color}")
    else:
        print("No solution")

if __name__ == "__main__":
    main()

