    names = ["Peter", "Eric", "Arnold", "Alice"]
    genres = ["jazz", "rock", "classical", "pop"]

    name_pos = {}
    for name in names:
        var = Int(name)
        name_pos[name] = var
        solver.add(var >= 1, var <= 4)

    genre_pos = {}
    for genre in genres:
        var = Int(genre)
        genre_pos[genre] = var
        solver.add(var >= 1, var <= 4)

    solver.add(Distinct(list(name_pos.values())))
    solver.add(Distinct(list(genre_pos.values())))

    # Alice is directly left of Peter.
    solver.add(name_pos["Alice"] + 1 == name_pos["Peter"])

    # The person who loves classical music is directly left of Peter.
    solver.add(genre_pos["classical"] + 1 == name_pos["Peter"])

    # Arnold is the person who loves jazz music.
    solver.add(name_pos["Arnold"] == genre_pos["jazz"])

    # The person who loves rock music is not in the second house.
    solver.add(genre_pos["rock"] != 2)

    # The person who loves rock music is directly left of the person who loves pop music.
    solver.add(genre_pos["rock"] + 1 == genre_pos["pop"])

    if solver.check() == sat:
        model = solver.model()

        for house in range(1, 5):
            name = next(
                n
                for n, var in name_pos.items()
                if model.evaluate(var, model_completion=True).as_long() == house
            )
            genre = next(
                g
                for g, var in genre_pos.items()
                if model.evaluate(var, model_completion=True).as_long() == house
            )
            print(f"House {house}: {name}, {genre}")
    else:
        print("No solution")

