def main():
    names = ["Arnold", "Peter", "Eric"]
    lunches = ["spaghetti", "grilled cheese", "pizza"]
    colors = ["yellow", "white", "red"]

    solver = Solver()

    name_pos = {n: Int(f"name_{n.replace(' ', '_')}") for n in names}
    lunch_pos = {l: Int(f"lunch_{l.replace(' ', '_')}") for l in lunches}
    color_pos = {c: Int(f"color_{c.replace(' ', '_')}") for c in colors}

    all_vars = list(name_pos.values()) + list(lunch_pos.values()) + list(color_pos.values())
    for var in all_vars:
        solver.add(var >= 1, var <= 3)

    solver.add(Distinct(*name_pos.values()))
    solver.add(Distinct(*lunch_pos.values()))
    solver.add(Distinct(*color_pos.values()))

    # 1. Red and yellow are next to each other.
    solver.add(
        Or(
            color_pos["red"] == color_pos["yellow"] + 1,
            color_pos["red"] == color_pos["yellow"] - 1
        )
    )

    # 2. The spaghetti eater is the person who loves yellow.
    solver.add(lunch_pos["spaghetti"] == color_pos["yellow"])

    # 3. Pizza and red are next to each other.
    solver.add(
        Or(
            lunch_pos["pizza"] == color_pos["red"] + 1,
            lunch_pos["pizza"] == color_pos["red"] - 1
        )
    )

    # 4. Peter is directly left of the spaghetti eater.
    solver.add(name_pos["Peter"] == lunch_pos["spaghetti"] - 1)

    # 5. The spaghetti eater is Eric.
    solver.add(name_pos["Eric"] == lunch_pos["spaghetti"])

    if solver.check() != sat:
        return

    model = solver.model()

    def get_pos(var):
        return model.eval(var).as_long()

    name_at = {get_pos(var): name for name, var in name_pos.items()}
    lunch_at = {get_pos(var): lunch for lunch, var in lunch_pos.items()}
    color_at = {get_pos(var): color for color, var in color_pos.items()}

    for house in range(1, 4):
        print(f"House {house}: {name_at[house]}, {lunch_at[house]}, {color_at[house]}")

