from z3 import *

def main():
    houses = [0, 1, 2]
    categories = {
        "name": ["Eric", "Arnold", "Peter"],
        "pet": ["dog", "fish", "cat"],
        "book": ["mystery", "romance", "science fiction"],
        "car": ["ford f150", "tesla model 3", "toyota camry"],
        "month": ["april", "jan", "sept"],
        "music": ["rock", "classical", "pop"],
    }

    solver = Solver()
    variables = {}

    def add_exactly_one(booleans):
        solver.add(Or(*booleans))
        for i in range(len(booleans)):
            for j in range(i + 1, len(booleans)):
                solver.add(Not(And(booleans[i], booleans[j])))

    for cat, vals in categories.items():
        n = len(vals)
        vs = [[Bool(f"{cat}_h{h}_v{i}") for i in range(n)] for h in houses]
        variables[cat] = vs

        for h in houses:
            add_exactly_one(vs[h])

        for i in range(n):
            add_exactly_one([vs[h][i] for h in houses])

    def value_index(cat, val):
        return categories[cat].index(val)

    def has(cat, val, h):
        return variables[cat][h][value_index(cat, val)]

    solver.add(
        Or(
            And(has("book", "romance", 0), has("car", "ford f150", 1)),
            And(has("book", "romance", 1), has("car", "ford f150", 2)),
        )
    )

    for h in houses:
        solver.add(Implies(has("month", "sept", h), has("car", "toyota camry", h)))
        solver.add(Implies(has("car", "toyota camry", h), has("month", "sept", h)))

        solver.add(Implies(has("month", "sept", h), has("name", "Peter", h)))
        solver.add(Implies(has("name", "Peter", h), has("month", "sept", h)))

        solver.add(Implies(has("car", "tesla model 3", h), has("month", "jan", h)))
        solver.add(Implies(has("month", "jan", h), has("car", "tesla model 3", h)))

        solver.add(Implies(has("name", "Arnold", h), has("pet", "cat", h)))
        solver.add(Implies(has("pet", "cat", h), has("name", "Arnold", h)))

        solver.add(Implies(has("car", "tesla model 3", h), has("book", "science fiction", h)))
        solver.add(Implies(has("book", "science fiction", h), has("car", "tesla model 3", h)))

        solver.add(Implies(has("car", "ford f150", h), has("music", "pop", h)))
        solver.add(Implies(has("music", "pop", h), has("car", "ford f150", h)))

    solver.add(Not(has("pet", "fish", 1)))
    solver.add(Not(has("book", "science fiction", 2)))

    solver.add(
        Or(
            And(has("music", "rock", 0), has("name", "Eric", 1)),
            And(has("music", "rock", 1), has("name", "Eric", 2)),
        )
    )

    if solver.check() == sat:
        model = solver.model()
        output = []

        for h in houses:
            attrs = []
            for cat in ["name", "pet", "book", "car", "month", "music"]:
                for i, val in enumerate(categories[cat]):
                    if is_true(model.eval(variables[cat][h][i])):
                        attrs.append(val)
                        break
            output.append(f"House {h + 1}: " + ", ".join(attrs))

        print("\n".join(output))

if __name__ == "__main__":
    main()

